from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass
from typing import Literal

from tvm.target import Target

TargetConfig = dict[str, object]
TargetInput = str | Mapping[str, object] | Target
TargetLike = str | TargetConfig | Target
TargetDetector = Callable[[], TargetInput | None]
TargetNormalizer = Callable[[TargetLike], TargetInput | None]


@dataclass(frozen=True, slots=True)
class TargetDetectorSpec:
    name: str
    detect: TargetDetector


@dataclass(frozen=True, slots=True)
class TargetNormalizerSpec:
    name: str
    normalize: TargetNormalizer


_TARGET_DETECTORS: dict[str, TargetDetectorSpec] = {}
_TARGET_NORMALIZERS: dict[str, TargetNormalizerSpec] = {}


def register_target_detector(
    name: str,
    detect: TargetDetector,
    *,
    override: bool = False,
) -> TargetDetectorSpec:
    if name in _TARGET_DETECTORS and not override:
        raise ValueError(f"Target detector {name!r} is already registered")
    spec = TargetDetectorSpec(name=name, detect=detect)
    _TARGET_DETECTORS[name] = spec
    return spec


def register_target_normalizer(
    name: str,
    normalize: TargetNormalizer,
    *,
    override: bool = False,
) -> TargetNormalizerSpec:
    if name in _TARGET_NORMALIZERS and not override:
        raise ValueError(f"Target normalizer {name!r} is already registered")
    spec = TargetNormalizerSpec(name=name, normalize=normalize)
    _TARGET_NORMALIZERS[name] = spec
    return spec


def _normalize_registered_target(target: TargetLike) -> TargetInput | None:
    for spec in _TARGET_NORMALIZERS.values():
        normalized = spec.normalize(target)
        if normalized is not None:
            return normalized
    return None


def auto_detect_target() -> TargetInput:
    errors: list[str] = []
    for spec in _TARGET_DETECTORS.values():
        try:
            detected = spec.detect()
        except Exception as err:
            errors.append(f"{spec.name}: {err}")
            continue
        if detected is not None:
            return detected

    details = f" Tried: {', '.join(errors)}." if errors else ""
    raise ValueError(f"No registered target detector found an available target.{details}")


def list_target_detectors() -> tuple[str, ...]:
    return tuple(_TARGET_DETECTORS)


def _validate_manual_target(target: TargetLike) -> TargetInput:
    normalized = _normalize_registered_target(target)
    if normalized is not None:
        return normalized

    if isinstance(target, Target):
        return target
    if isinstance(target, dict):
        try:
            Target(target)
        except Exception as err:
            raise AssertionError(f"Target {target} is not supported. Pass a valid target config dict.") from err
        return target
    if isinstance(target, str):
        normalized_target = target.strip()
        if not normalized_target:
            raise AssertionError(f"Target {target} is not supported")
        try:
            Target(normalized_target)
        except Exception as err:
            raise AssertionError(
                f"Target {target} is not supported. Pass target options as a dict when the target needs attributes."
            ) from err
        return normalized_target
    raise AssertionError(f"Target {target} is not supported")


def _finalize_target(target: TargetInput, *, return_object: bool) -> str | Mapping[str, object] | Target:
    if isinstance(target, (str, dict, Target)):
        normalized = _normalize_registered_target(target)
        if normalized is not None:
            target = normalized
    if return_object and not isinstance(target, Target):
        return Target(target)
    return target


def determine_target(target: TargetLike | Literal["auto"] = "auto", return_object: bool = False) -> str | Mapping[str, object] | Target:
    """
    Determine and validate the target for compilation.

    Target detection and normalization is provided by registered target modules.
    """
    if target == "auto":
        current_target = Target.current(allow_none=True)
        return_var = current_target if current_target is not None else auto_detect_target()
    else:
        return_var = _validate_manual_target(target)

    return _finalize_target(return_var, return_object=return_object)

from __future__ import annotations

from tvm.target import Target

from tilelang.backend.target import TargetLike, register_target_detector, register_target_normalizer


def _target_ffi_api():
    from tilelang import _ffi_api

    return _ffi_api


def check_cuda_availability() -> bool:
    """
    Check if CUDA is available on the system by locating the CUDA path.
    Returns:
        bool: True if CUDA is available, False otherwise.
    """
    try:
        from tilelang.contrib import nvcc

        nvcc.find_cuda_path()
        return True
    except Exception:
        return False


def _detect_torch_cuda_arch() -> str | None:
    """Return the CUDA SM architecture detected from PyTorch, if available."""
    import torch

    from tilelang.contrib import nvcc

    if not torch.cuda.is_available():
        return None
    cap = torch.cuda.get_device_capability(torch.cuda.current_device())
    return f"sm_{nvcc.get_target_arch(cap)}" if cap else None


def _cuda_target_from_arch(arch: str | None) -> Target | str:
    """Build a CUDA target while preserving the legacy bare string fallback."""
    if arch is None:
        return "cuda"
    return Target({"kind": "cuda", "arch": arch})


def _detect_cuda_target() -> Target | str | None:
    import torch

    if torch.version.hip is not None:
        return None
    if not check_cuda_availability():
        return None

    arch = _detect_torch_cuda_arch()
    return _cuda_target_from_arch(arch)


def normalize_cuda_target(target: TargetLike) -> Target | None:
    if not isinstance(target, str) or target.strip() != "cuda":
        return None
    normalized = _cuda_target_from_arch(_detect_torch_cuda_arch())
    return normalized if isinstance(normalized, Target) else None


def _with_cutedsl_key(target: Target | str) -> Target:
    if not isinstance(target, Target):
        target = Target(target)
    target_dict = dict(target.export())
    target_dict["keys"] = list(dict.fromkeys([*target_dict.get("keys", ()), "cutedsl"]))
    return Target(target_dict)


def normalize_cutedsl_target(target: TargetLike) -> Target | None:
    if isinstance(target, Target):
        if target.kind.name == "cuda" and "cutedsl" in target.keys:
            return target
        return None

    if isinstance(target, dict):
        if target.get("kind") == "cutedsl":
            cuda_target = dict(target)
            cuda_target["kind"] = "cuda"
            try:
                return _with_cutedsl_key(Target(cuda_target))
            except Exception:
                return None
        try:
            temp_target = Target(target)
        except Exception:
            return None
        if temp_target.kind.name == "cuda" and "cutedsl" in temp_target.keys:
            return temp_target
        return None

    if target.strip() == "cutedsl":
        try:
            return _with_cutedsl_key(_cuda_target_from_arch(_detect_torch_cuda_arch()))
        except Exception:
            return None

    return None


def _normalize_cutedsl_target_for_resolve(target: TargetLike) -> Target | None:
    normalized = normalize_cutedsl_target(target)
    if normalized is None:
        return None
    try:
        from tilelang.jit.adapter.cutedsl.checks import check_cutedsl_available

        check_cutedsl_available()
    except ImportError as err:
        raise AssertionError(f"CuTeDSL backend is not available. Please install tilelang-cutedsl package. {str(err)}") from err
    return normalized


def target_is_cuda(target: Target) -> bool:
    return _target_ffi_api().TargetIsCuda(target)


def target_is_volta(target: Target) -> bool:
    return _target_ffi_api().TargetIsVolta(target)


def target_is_turing(target: Target) -> bool:
    return _target_ffi_api().TargetIsTuring(target)


def target_is_ampere(target: Target) -> bool:
    return _target_ffi_api().TargetIsAmpere(target)


def target_is_hopper(target: Target) -> bool:
    return _target_ffi_api().TargetIsHopper(target)


def target_is_sm120(target: Target) -> bool:
    return _target_ffi_api().TargetIsSM120(target)


def target_has_async_copy(target: Target) -> bool:
    return _target_ffi_api().TargetHasAsyncCopy(target)


def target_has_ldmatrix(target: Target) -> bool:
    return _target_ffi_api().TargetHasLdmatrix(target)


def target_has_stmatrix(target: Target, is_m16n8: bool = False) -> bool:
    return _target_ffi_api().TargetHasStmatrix(target, is_m16n8)


def target_has_bulk_copy(target: Target) -> bool:
    return _target_ffi_api().TargetHasBulkCopy(target)


register_target_detector("cuda", _detect_cuda_target, override=True)
register_target_normalizer("cuda", normalize_cuda_target, override=True)
register_target_normalizer("cutedsl", _normalize_cutedsl_target_for_resolve, override=True)

from __future__ import annotations

from tvm.target import Target

from tilelang.backend.target import TargetLike, register_target_detector, register_target_normalizer

ROCM_MTRIPLE = "amdgcn-amd-amdhsa-hcc"


def _target_ffi_api():
    from tilelang import _ffi_api

    return _ffi_api


def normalize_rocm_arch(arch: str | None) -> str | None:
    if arch is None:
        return None
    normalized = str(arch).strip().split(":", maxsplit=1)[0]
    return normalized if normalized.startswith("gfx") else None


def target_get_mcpu(target: str | Target | None) -> str | None:
    if target is None:
        return None
    if isinstance(target, str):
        target = Target(target)
    return normalize_rocm_arch(target.attrs.get("mcpu"))


def rocm_warp_size_for_arch(arch: str | None) -> int | None:
    if arch is None:
        return None
    if arch.startswith("gfx9"):
        return 64
    if arch.startswith(("gfx10", "gfx11", "gfx12")):
        return 32
    return None


def with_rocm_target_attrs(target: Target) -> Target:
    if target.kind.name != "hip":
        return target
    arch = target_get_mcpu(target)
    if arch is None:
        return target

    target_dict = dict(target.export())
    target_dict.setdefault("mtriple", ROCM_MTRIPLE)
    warp_size = rocm_warp_size_for_arch(arch)
    if warp_size is not None:
        target_dict["thread_warp_size"] = warp_size
    else:
        target_dict.pop("thread_warp_size", None)
    return Target(target_dict)


def _detect_rocm_arch() -> str | None:
    try:
        import torch

        if torch.cuda.is_available():
            return normalize_rocm_arch(getattr(torch.cuda.get_device_properties(0), "gcnArchName", None))
    except Exception:
        pass
    return None


def _target_from_arch(arch: str | None) -> Target | str:
    if arch is None:
        return "hip"
    target_dict: dict[str, object] = {
        "kind": "hip",
        "mcpu": arch,
        "mtriple": ROCM_MTRIPLE,
    }
    warp_size = rocm_warp_size_for_arch(arch)
    if warp_size is not None:
        target_dict["thread_warp_size"] = warp_size
    return Target(target_dict)


def check_hip_availability() -> bool:
    """
    Check if HIP (ROCm) is available on the system by locating the ROCm path.
    Returns:
        bool: True if HIP is available, False otherwise.
    """
    try:
        from tvm.contrib import rocm

        rocm.find_rocm_path()
        return True
    except Exception:
        return False


def _detect_rocm_target() -> Target | str | None:
    if not check_hip_availability():
        return None

    return _target_from_arch(_detect_rocm_arch())


def normalize_rocm_target(target: TargetLike) -> Target | None:
    if isinstance(target, Target):
        parsed_target = target
    elif isinstance(target, dict):
        if target.get("kind") != "hip":
            return None
        try:
            parsed_target = Target(target)
        except Exception:
            return None
    else:
        return None

    if parsed_target.kind.name != "hip":
        return None
    if target_get_mcpu(parsed_target) is None:
        return parsed_target if isinstance(target, Target) else None
    return with_rocm_target_attrs(parsed_target)


def target_is_hip(target: Target) -> bool:
    return _target_ffi_api().TargetIsRocm(target)


def target_is_cdna(target: Target) -> bool:
    return _target_ffi_api().TargetIsCDNA(target)


def target_is_rdna(target: Target) -> bool:
    return _target_ffi_api().TargetIsRDNA(target)


def target_is_gfx950(target: Target) -> bool:
    return _target_ffi_api().TargetIsGfx950(target)


def target_get_warp_size(target: Target) -> int:
    return _target_ffi_api().TargetRocmGetWarpSize(target)


def target_get_rdna_generation(target: Target) -> int:
    return _target_ffi_api().TargetGetRDNAGeneration(target)


register_target_detector("hip", _detect_rocm_target, override=True)
register_target_normalizer("hip", normalize_rocm_target, override=True)

