"""Device codegen registry shared by backend packages."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from importlib import import_module

from tvm import IRModule
from tvm.target import Target

from tilelang import tvm

DeviceCodegenFunc = Callable[[IRModule, Target], IRModule]
TargetPredicate = Callable[[Target], bool]


def global_func_device_codegen(global_func_name: str) -> DeviceCodegenFunc:
    """Create a device codegen callback backed by a TVM global function."""

    def build(mod: IRModule, target: Target) -> IRModule:
        return tvm.ffi.get_global_func(global_func_name)(mod, target)

    return build


@dataclass(frozen=True, slots=True)
class DeviceCodegen:
    """Device codegen entry points for one backend target variant."""

    name: str
    build: DeviceCodegenFunc | None = None
    build_without_compile: DeviceCodegenFunc | None = None
    supports_target: TargetPredicate | None = None

    def matches(self, target: Target) -> bool:
        return True if self.supports_target is None else self.supports_target(target)

    def lower(self, mod: IRModule, target: Target, *, compile_device: bool) -> IRModule:
        build_func = self.build if compile_device else self.build_without_compile
        if build_func is None:
            mode = "with compilation" if compile_device else "without compilation"
            raise ValueError(f"Device codegen '{self.name}' for target '{target.kind.name}' does not support lowering {mode}")
        return build_func(mod, target)


_DEVICE_CODEGENS: dict[str, list[DeviceCodegen]] = {}
_LAZY_DEVICE_CODEGENS: dict[str, str] = {}
_LOADED_DEVICE_CODEGENS: set[str] = set()


def register_device_codegen(
    target_kind: str,
    codegen: DeviceCodegen,
    *,
    override: bool = False,
) -> DeviceCodegen:
    """Register a device codegen entry for a target kind."""

    codegens = _DEVICE_CODEGENS.setdefault(target_kind, [])
    if override:
        codegens[:] = [item for item in codegens if item.name != codegen.name]
    elif any(item.name == codegen.name for item in codegens):
        raise ValueError(f"Device codegen {codegen.name!r} is already registered for target kind {target_kind!r}")
    codegens.append(codegen)
    return codegen


def register_lazy_device_codegen(target_kind: str, import_path: str) -> None:
    """Register a backend module to import when its target kind is first used."""

    _LAZY_DEVICE_CODEGENS[target_kind] = import_path
    _LOADED_DEVICE_CODEGENS.discard(target_kind)


def _ensure_device_codegens_loaded(target_kind: str) -> None:
    if target_kind in _LOADED_DEVICE_CODEGENS:
        return
    import_path = _LAZY_DEVICE_CODEGENS.get(target_kind)
    if import_path is not None:
        import_module(import_path)
    _LOADED_DEVICE_CODEGENS.add(target_kind)


def _matching_device_codegens(target: Target) -> list[DeviceCodegen]:
    target_kind = target.kind.name
    _ensure_device_codegens_loaded(target_kind)
    return [codegen for codegen in _DEVICE_CODEGENS.get(target_kind, ()) if codegen.matches(target)]


def allowed_device_codegens_for_target(target: Target) -> list[str]:
    """Return matching device codegen names for a target."""

    return [codegen.name for codegen in _matching_device_codegens(target)]


def _format_codegen_names(codegens: list[DeviceCodegen]) -> str:
    names = [codegen.name for codegen in codegens]
    return ", ".join(names) if names else "<none>"


def resolve_device_codegen(target: Target) -> DeviceCodegen:
    """Resolve a device codegen entry from a TVM target."""

    matches = _matching_device_codegens(target)
    if not matches:
        target_kind = target.kind.name
        options = _format_codegen_names(_DEVICE_CODEGENS.get(target_kind, []))
        raise ValueError(f"No device codegen registered for target '{target_kind}'. Available: {options}.")
    return matches[0]

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from importlib import import_module

from tvm.target import Target

TargetPredicate = Callable[[Target], bool]
AvailabilityCheck = Callable[[], bool]

_CANONICAL_EXECUTION_BACKENDS = {
    "dlpack": "tvm_ffi",
}


def _always_available() -> bool:
    return True


def canonicalize_execution_backend(name: str | None) -> str | None:
    if name is None:
        return None
    key = str(name).lower()
    return _CANONICAL_EXECUTION_BACKENDS.get(key, key)


@dataclass(frozen=True, slots=True)
class ExecutionBackendSpec:
    name: str
    is_available: AvailabilityCheck = _always_available
    supports_target: TargetPredicate | None = None
    enable_host_codegen: bool = False
    enable_device_compile: bool = False

    def matches(self, target: Target) -> bool:
        return True if self.supports_target is None else self.supports_target(target)


_EXECUTION_BACKENDS: dict[str, list[ExecutionBackendSpec]] = {}
_LAZY_EXECUTION_BACKENDS: dict[str, str] = {}
_LOADED_EXECUTION_BACKENDS: set[str] = set()


def register_execution_backend(
    target_kind: str,
    spec: ExecutionBackendSpec,
    *,
    override: bool = False,
) -> ExecutionBackendSpec:
    specs = _EXECUTION_BACKENDS.setdefault(target_kind, [])
    if override:
        specs[:] = [item for item in specs if item.name != spec.name]
    elif any(item.name == spec.name for item in specs):
        raise ValueError(f"Execution backend {spec.name!r} is already registered for target kind {target_kind!r}")
    specs.append(spec)
    return spec


def register_lazy_execution_backends(target_kind: str, import_path: str) -> None:
    _LAZY_EXECUTION_BACKENDS[target_kind] = import_path


def _ensure_execution_backends_loaded(target_kind: str) -> None:
    if target_kind in _LOADED_EXECUTION_BACKENDS:
        return
    import_path = _LAZY_EXECUTION_BACKENDS.get(target_kind)
    if import_path is not None:
        import_module(import_path)
    _LOADED_EXECUTION_BACKENDS.add(target_kind)


def _matching_specs(target: Target, *, include_unavailable: bool) -> list[ExecutionBackendSpec]:
    target_kind = target.kind.name
    _ensure_execution_backends_loaded(target_kind)
    specs = [spec for spec in _EXECUTION_BACKENDS.get(target_kind, ()) if spec.matches(target)]
    if not include_unavailable:
        specs = [spec for spec in specs if spec.is_available()]
    return specs


def allowed_backends_for_target(target: Target, *, include_unavailable: bool = True) -> list[str]:
    return [spec.name for spec in _matching_specs(target, include_unavailable=include_unavailable)]


def _format_options(options: list[str]) -> str:
    return ", ".join(options) if options else "<none>"


def resolve_execution_backend(requested: str | None, target: Target) -> str:
    return resolve_execution_backend_spec(requested, target).name


def resolve_execution_backend_spec(requested: str | None, target: Target) -> ExecutionBackendSpec:
    requested_name = canonicalize_execution_backend(requested)
    allowed_all_specs = _matching_specs(target, include_unavailable=True)
    allowed_available_specs = _matching_specs(target, include_unavailable=False)
    allowed_all = [spec.name for spec in allowed_all_specs]
    allowed_available = [spec.name for spec in allowed_available_specs]

    if requested_name in (None, "auto"):
        if not allowed_available_specs:
            raise ValueError(f"No available execution backend for target '{target.kind.name}'. Allowed: {_format_options(allowed_all)}.")
        return allowed_available_specs[0]

    if requested_name not in allowed_all:
        raise ValueError(
            f"Invalid execution backend '{requested}' for target '{target.kind.name}'. "
            f"Allowed: {_format_options(allowed_all)}. Tip: use execution_backend='auto'."
        )
    if requested_name not in allowed_available:
        raise ValueError(
            f"Execution backend '{requested}' requires extra dependencies and is not available now. "
            f"Try one of: {_format_options(allowed_available)}."
        )
    return next(spec for spec in allowed_available_specs if spec.name == requested_name)

